 public void Control(string json){var input=JsonUtility.FromJson<ForgeControl>(json);if(input.key=="clear"){if(destinationAction=="begin"&&route!=null)Send("settled",strikeSeq,"",-1);heldKeys.Clear();movement=Vector2.zero;touchMoving=false;route=null;destination="";return;}if(input.down)heldKeys.Add(input.key);else heldKeys.Remove(input.key);if(!input.down)return;
