 void PlayerPointer(ForgePointer p){if(smith==null||state?.ended==true)return;if(p.phase=="down"){pointerStarted=Time.unscaledTime;touchOrigin=touchLast=new Vector2(p.x,p.y);touchMoving=false;Send("gesture");}else if(p.phase=="move"){var at=new Vector2(p.x,p.y);if(Vector2.Distance(at,touchOrigin)>.015f){{workFocus=false;orbitYaw+=(at.x-touchLast.x)*190;orbitPitch=Mathf.Clamp(orbitPitch+(at.y-touchLast.y)*100,-65,78);touchLast=at;touchMoving=false;}}}else if(p.phase=="up"){bool tap=Vector2.Distance(new Vector2(p.x,p.y),touchOrigin)<.015f;touchMoving=false;movement=Vector2.zero;if(tap&&workFocus&&p.x>.16f&&p.x<.84f&&p.y>.3f&&p.y<.77f){TryStrike();return;}if(tap){var ray=cam.ViewportPointToRay(new Vector3(p.x,1-p.y));string best="";float score=.95f;foreach(var spot in spots){var along=Vector3.Dot(spot.Value-ray.origin,ray.direction);if(along<0)continue;float d=Vector3.Distance(ray.GetPoint(along),spot.Value);if(d<score){score=d;best=spot.Key;}}if(best!=""){if(best=="shop"||best=="lantern"){GoTo(best,"approach");Send("notice",0,best=="shop"?"Trade · T or Handle":"Rest · hold Handle or E");return;}if(nearby==best){if(best=="anvil"&&carriedId<0&&Time.unscaledTime-pointerStarted<.45f)TryStrike();else if(best=="lantern"){Send("spot",0,"lantern");}else Interact();}else GoTo(best);}}}else if(p.phase=="cancel"){touchMoving=false;movement=Vector2.zero;}}
 void GoTo(string station,string action="interact"){destinationAction=action;var goal=approaches[station];var start=smith.position;var path=new List<Vector3>();bool crosses=false;for(int i=1;i<=20;i++)if(!Walkable(Vector3.Lerp(start,goal,i/20f))){crosses=true;break;}if(crosses){float side=Mathf.Clamp(start.x,-3.2f,3.2f);float fromZ=-1.5f;float toZ=-1.5f;path.Add(new Vector3(start.x,0,fromZ));path.Add(new Vector3(side,0,fromZ));path.Add(new Vector3(side,0,toZ));path.Add(new Vector3(goal.x,0,toZ));}path.Add(goal);route=path.ToArray();routeIndex=0;destination=station;}
